{{ config(materialized='table', schema='ENVIRONMENT') }}

-- Source: FED_EPA_SDWA_SDWA_GEOGRAPHIC_AREAS (578,198 rows)  [row count re-verified against the live table 2026-08-11; header had said 500000]
-- Generated by scripts/gen_mart_models.py
-- 2026-09-10: COUNTY_FIPS added. St./Saint are folded to SAINT; city forms keep their suffix so
-- St. Louis city and St. Louis County stay apart. Measured 404,823 of 405,396 county rows matched.
-- Earlier note: COUNTY_SERVED is a bare name and STATE_SERVED is blank on
-- county rows, so the state comes from the PWSID prefix and the name is matched to the Census
-- 2020 county list with the legal suffix stripped. Measured before the change: 404,653 of
-- 405,396 county rows match, no fan-out. Misses are accented names and renamed Alaska areas.

with source as (
    select * from {{ source('ripple_raw', 'FED_EPA_SDWA_SDWA_GEOGRAPHIC_AREAS') }}
),

county_dim as (
    select
        STATE as state_abbr,
        STATEFP || COUNTYFP as county_fips,
        upper(regexp_replace(regexp_replace(regexp_replace(COUNTYNAME,
            '[[:space:]]+(County|Parish|Borough|Census Area|Municipio|Municipality)$', '', 1, 0, 'i'),
            '^(St\.?|Saint)[[:space:]]+', 'SAINT ', 1, 0, 'i'),
            '[^A-Za-z0-9]', '')) as name_key,
        row_number() over (
            partition by STATE, upper(regexp_replace(regexp_replace(regexp_replace(COUNTYNAME,
            '[[:space:]]+(County|Parish|Borough|Census Area|Municipio|Municipality)$', '', 1, 0, 'i'),
            '^(St\.?|Saint)[[:space:]]+', 'SAINT ', 1, 0, 'i'),
            '[^A-Za-z0-9]', ''))
            order by case when CLASSFP in ('H1', 'H4', 'H5') then 0 else 1 end, COUNTYFP
        ) as rn
    from {{ source('ripple_raw', 'FED_CENSUS_COUNTY_2020') }}
)

select
    s.SUBMISSIONYEARQUARTER as submissionyearquarter,
    s.PWSID as pwsid,
    s.GEO_ID as geo_id,
    s.AREA_TYPE_CODE as area_type_code,
    s.TRIBAL_CODE as tribal_code,
    s.STATE_SERVED as state_served,
    s.ANSI_ENTITY_CODE as ansi_entity_code,
    s.ZIP_CODE_SERVED as zip_code_served,
    s.CITY_SERVED as city_served,
    s.COUNTY_SERVED as county_served,
    d.county_fips as county_fips,
    try_to_date(s.LAST_REPORTED_DATE) as last_reported_date
from source s
left join county_dim d
    on d.rn = 1
   and d.state_abbr = left(s.PWSID, 2)
   and d.name_key = upper(regexp_replace(regexp_replace(regexp_replace(s.COUNTY_SERVED,
            '[[:space:]]+(County|Parish|Borough|Census Area|Municipio|Municipality)$', '', 1, 0, 'i'),
            '^(St\.?|Saint)[[:space:]]+', 'SAINT ', 1, 0, 'i'),
            '[^A-Za-z0-9]', ''))
